/**
 * Error Wrapping Utilities
 *
 * Provides utilities for wrapping unknown errors as VeryfrontError instances
 * with the unknown-error slug. Used at system boundaries to ensure all errors
 * have slug-based identity.
 *
 * @module errors/middleware/wrap-unknown
 */
import { isVeryfrontErrorInstance, snapshotKnownVeryfrontError, VeryfrontError } from "../types.js";
import { UNKNOWN_ERROR } from "../error-registry.js";
import { snapshotKnownError } from "../veryfront-error.js";
import { redactForSerialization } from "../../utils/logger/redact.js";
import { detachThrowableForBoundary } from "../safe-diagnostics.js";
import { isNativeErrorWithoutHooks } from "../../platform/compat/error-introspection.js";
const arrayIsArray = Array.isArray;
function snapshotContext(context) {
    if (!context)
        return undefined;
    const snapshot = redactForSerialization(context);
    return snapshot && typeof snapshot === "object" && !arrayIsArray(snapshot)
        ? snapshot
        : undefined;
}
/**
 * Return a detached VeryfrontError, preserving safe identity fields from valid VeryfrontError inputs
 *
 * This function is used at system boundaries (HTTP, CLI, etc.) to ensure
 * all errors have slug-based identity for consistent handling.
 *
 * @param error - A valid VeryfrontError to detach, or another value to wrap as unknown-error
 * @param context - Optional context added only when error is not a valid VeryfrontError
 * @returns A detached, framework-owned VeryfrontError. Valid VeryfrontError
 * inputs retain safe identity fields; other inputs use the unknown-error slug.
 *
 * @example
 * ```typescript
 * try {
 *   // Some operation
 * } catch (error) {
 *   const vfError = wrapUnknownError(error);
 *   return createErrorResponse(vfError);
 * }
 * ```
 */
export function wrapUnknownError(error, context) {
    const detached = detachThrowableForBoundary(error);
    if (isVeryfrontErrorInstance(detached)) {
        return detached;
    }
    return UNKNOWN_ERROR.create({
        detail: detached.message,
        cause: isNativeErrorWithoutHooks(error) ? error : undefined,
        context: snapshotContext(context),
    });
}
/**
 * Detach a thrown value at a system boundary, then normalize the stable copy.
 *
 * This prevents stateful Error proxies from reporting different identities to
 * observability, formatting, and the final response.
 */
export function detachBoundaryError(error) {
    const detached = detachThrowableForBoundary(error);
    return isVeryfrontErrorInstance(detached) ? detached : UNKNOWN_ERROR.create({
        detail: detached.message,
        cause: detached,
    });
}
/**
 * Wrap an error with additional context
 *
 * If the error is already a VeryfrontError, preserves its slug and adds context.
 * If the error is a plain Error, wraps it as unknown-error.
 *
 * @param error - Any error value
 * @param message - Additional message to prepend
 * @param context - Additional context to add
 * @returns VeryfrontError with added context
 *
 * @example
 * ```typescript
 * try {
 *   await fetchData();
 * } catch (error) {
 *   throw wrapWithContext(error, "Failed to fetch data", { userId: 123 });
 * }
 * ```
 */
export function wrapWithContext(error, message, context) {
    const extraContext = snapshotContext(context);
    // If already a VeryfrontError, preserve slug but update message/context
    if (isVeryfrontErrorInstance(error)) {
        const snapshot = snapshotKnownVeryfrontError(error);
        if (!snapshot) {
            return UNKNOWN_ERROR.create({
                detail: `${message}: Unknown error`,
                context: extraContext,
            });
        }
        const combinedMessage = `${message}: ${snapshot.message}`;
        const originalContext = snapshot.context && typeof snapshot.context === "object"
            ? snapshotContext(snapshot.context)
            : undefined;
        return new VeryfrontError(combinedMessage, {
            slug: snapshot.slug,
            category: snapshot.category,
            status: snapshot.status,
            title: snapshot.title,
            suggestion: snapshot.suggestion,
            exitCode: snapshot.exitCode,
            detail: combinedMessage,
            cause: snapshot.cause,
            instance: snapshot.instance,
            context: {
                ...originalContext,
                ...extraContext,
                originalError: {
                    message: snapshot.message,
                    slug: snapshot.slug,
                },
            },
        });
    }
    if (isNativeErrorWithoutHooks(error)) {
        const snapshot = snapshotKnownError(error);
        const originalMessage = snapshot?.message ?? "Unknown error";
        return UNKNOWN_ERROR.create({
            detail: `${message}: ${originalMessage}`,
            cause: snapshot ? error : undefined,
            context: {
                ...extraContext,
                originalMessage,
            },
        });
    }
    const originalMessage = detachThrowableForBoundary(error).message;
    return UNKNOWN_ERROR.create({
        detail: `${message}: ${originalMessage}`,
        context: {
            ...extraContext,
            originalMessage,
        },
    });
}
